package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type LedgerRec struct {
	BrBranch string
	BrAcct   string
	BrType   string
	BrAmt    decimal.Decimal
}

var WsEofFlag string = "N"
var WsFirstFlag string = "Y"
var WsPrevBranch string = "  "
var WsPrevAcct string = "    "
var WsBal decimal.Decimal = decimal.NewFromInt(0)
var WsBranchTot decimal.Decimal = decimal.NewFromInt(0)
var WsGrandTot decimal.Decimal = decimal.NewFromInt(0)
var WsSkipped int64 = 0
var WsAmtEd string
var WsBalEd string
var WsTotEd string

var ledgerFile *os.File
var ledgerReader *bufio.Scanner
var currentLedgerRec LedgerRec
var ledgerRecRaw string

func isInputDone() bool { return WsEofFlag == "Y" }
func isFirstRecord() bool { return WsFirstFlag == "Y" }

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func parseAmt(s string) decimal.Decimal {
	s = strings.TrimSpace(s)
	if s == "" {
		return decimal.Zero
	}
	// digits only
	// may contain spaces? assume digits
	d := decimal.RequireFromString(s)
	// PIC 9(5)V99 => implied 2 decimals
	return decimal.New(d.IntPart(), -2)
}

// Formatting helpers

func formatAmtEd(d decimal.Decimal) string {
	// PIC ZZ,ZZ9.99 len 9
	// pattern: positions: 0:Z 1:, 2:Z 3:Z 4:, 5:Z 6:Z 7:9 8:. 9:9 9:9 ??? Wait compute
	// Actually "ZZ,ZZ9.99" length = 9 ?
	// Let's count: Z Z , Z Z 9 . 9 9 = 9 chars. Yes.
	return formatNumericEdited(d, "ZZ,ZZ9.99", false)
}

func formatBalEd(d decimal.Decimal) string {
	// PIC -Z,ZZZ,ZZ9.99 len 13
	return formatNumericEdited(d, "-Z,ZZZ,ZZ9.99", true)
}

func formatTotEd(d decimal.Decimal) string {
	// PIC -ZZZ,ZZZ,ZZ9.99 len 15
	return formatNumericEdited(d, "-ZZZ,ZZZ,ZZ9.99", true)
}

func formatNumericEdited(d decimal.Decimal, pic string, signed bool) string {
	// Extract sign
	neg := d.IsNegative()
	if neg {
		d = d.Neg()
	}
	// Truncate toward zero to 2 decimals (scale of pic is 2)
	d = d.Truncate(2)

	// Determine integer digits required in pic: count of Z and 9 before decimal
	// And fractional digits: count after .
	dotIdx := strings.Index(pic, ".")
	intPic := pic
	fracLen := 0
	if dotIdx >= 0 {
		intPic = pic[:dotIdx]
		fracLen = len(pic) - dotIdx - 1
	}
	// For signed, first char is '-' placeholder, not counted as digit
	signPlaceholder := false
	if signed && len(intPic) > 0 && intPic[0] == '-' {
		signPlaceholder = true
		intPic = intPic[1:]
	}
	// Count integer digit slots
	intSlots := 0
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			intSlots++
		}
	}
	// Get integer and fractional parts as strings
	// Use string representation with 2 decimals
	// d is non-negative
	intPart := d.IntPart()
	// fractional part
	fracPart := ""
	if fracLen > 0 {
		// get fractional digits truncated
		// compute: d - intPart
		fracDec := d.Sub(decimal.NewFromInt(intPart))
		// shift
		fracInt := fracDec.Shift(int32(fracLen)).Truncate(0).IntPart()
		fracPart = fmt.Sprintf("%0*d", fracLen, fracInt)
		// handle overflow due to truncation? no
	}
	intStrRaw := fmt.Sprintf("%d", intPart)
	// Drop high-order digits if overflow
	if len(intStrRaw) > intSlots {
		intStrRaw = intStrRaw[len(intStrRaw)-intSlots:]
	}
	// Pad integer string on left with zeros to intSlots
	intStrPadded := strings.Repeat("0", intSlots-len(intStrRaw)) + intStrRaw

	// Now map digits to picture positions
	// Build result for integer part
	intResult := make([]byte, len(intPic))
	digitIdx := 0
	// digitIdx indexes into intStrPadded
	for i := 0; i < len(intPic); i++ {
		c := intPic[i]
		if c == 'Z' || c == '9' {
			intResult[i] = intStrPadded[digitIdx]
			digitIdx++
		} else {
			// comma
			intResult[i] = byte(c)
		}
	}
	// Apply Z suppression: leading zeros in Z positions become spaces, commas in suppressed zone become spaces
	// Z-suppressed zone: from start until last Z that is before a non-zero? Actually COBOL: Z suppresses leading zeros, and commas inside suppressed are spaces.
	// All Z positions; 9 positions always shown.
	// Suppression continues until we encounter a non-zero digit in the integer part, or we reach the last Z? Need to interpret.
	// For pattern ZZ,ZZ9 : Z's are suppressed; if value is 0 => last digit (9) shows 0, preceding Z's are spaces.
	// Comma handling: if all digits to left of comma are suppressed (spaces), comma becomes space.
	// Simpler: iterate integer digit positions, track if we have seen non-zero.
	suppressing := true
	// Find which positions correspond to digit slots
	// We need to know for each intResult position that is digit, whether it's Z or 9
	// We'll walk left to right
	for i := 0; i < len(intPic); i++ {
		pc := intPic[i]
		if pc == 'Z' || pc == '9' {
			ch := intResult[i]
			if pc == '9' {
				// always show digit, end suppression
				suppressing = false
			} else { // Z
				if suppressing {
					if ch == '0' {
						// check if there is any non-zero digit later within integer part that would cause this zero to be needed? No, in COBOL leading zeros are suppressed even if they are zero, until non-zero.
						// If all remaining integer digits (including 9) are zero, we still suppress this zero.
						// Determine if there exists a non-zero digit at or after this position (in digit sequence)
						// Actually we need to see if any digit to the right (within int slots) is non-zero.
						// If not, this zero should be suppressed.
						hasNonZeroAhead := false
						// look ahead in intResult for digit positions
						for k := i + 1; k < len(intPic); k++ {
							if intPic[k] == 'Z' || intPic[k] == '9' {
								if intResult[k] != '0' {
									hasNonZeroAhead = true
									break
								}
							}
						}
						if hasNonZeroAhead {
							// This zero is leading zero before non-zero -> suppress
							intResult[i] = ' '
						} else {
							// All remaining digits zero -> suppress this zero as well (since 9 will show 0)
							intResult[i] = ' '
						}
					} else {
						// non-zero digit ends suppression
						suppressing = false
					}
				}
			}
		}
	}
	// Now commas in suppressed zone become spaces: a comma becomes space if all digit positions to its left are spaces (i.e., suppressed)
	for i := 0; i < len(intPic); i++ {
		if intPic[i] == ',' {
			// check if any digit to left is not space
			hasVisibleLeft := false
			for k := 0; k < i; k++ {
				if intPic[k] == 'Z' || intPic[k] == '9' {
					if intResult[k] != ' ' {
						hasVisibleLeft = true
						break
					}
				}
			}
			// also if comma is at start suppressed
			if !hasVisibleLeft {
				intResult[i] = ' '
				// Note: if suppression had ended later, comma after visible digits remains
			}
			// Additionally, if all integer digits are suppressed (value zero), comma should be space regardless
		}
	}

	// Build final string
	var sb strings.Builder
	if signed {
		if neg {
			sb.WriteByte('-')
		} else {
			sb.WriteByte(' ')
		}
	}
	sb.Write(intResult)
	if dotIdx >= 0 {
		sb.WriteByte('.')
		sb.WriteString(fracPart)
	}
	// Ensure length matches pic length
	out := sb.String()
	// pic length includes sign placeholder if signed
	expectedLen := len(pic)
	if len(out) < expectedLen {
		out = strings.Repeat(" ", expectedLen-len(out)) + out
	} else if len(out) > expectedLen {
		out = out[len(out)-expectedLen:]
	}
	return out
}

func main() {
	var err error
	ledgerFile, err = os.Open("input.dat")
	if err != nil {
		// If file not found, treat as empty
		if os.IsNotExist(err) {
			ledgerReader = nil
		} else {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
	}
	if ledgerFile != nil {
		ledgerReader = bufio.NewScanner(ledgerFile)
		// Don't drop long lines; default split by line
	}

	MAIN_PARA()

	if ledgerFile != nil {
		ledgerFile.Close()
	}
}

func MAIN_PARA() {
	if ledgerReader != nil {
		// OPEN INPUT simulated
	}
	READ_PARA()
	for !isInputDone() {
		PROCESS_PARA()
	}
	if !isFirstRecord() {
		ACCT_BREAK_PARA()
