func READ_PARA() {
	if ledgerReader == nil {
		WsEofFlag = "Y"
		return
	}
	if !ledgerReader.Scan() {
		WsEofFlag = "Y"
		return
	}
	line := ledgerReader.Text()
	// pad with spaces to 14
	if len(line) < 14 {
		line = line + strings.Repeat(" ", 14-len(line))
	} else if len(line) > 14 {
		line = line[:14]
	}
	ledgerRecRaw = line
	currentLedgerRec.BrBranch = line[0:2]
	currentLedgerRec.BrAcct = line[2:6]
	currentLedgerRec.BrType = line[6:7]
	currentLedgerRec.BrAmt = parseAmt(line[7:14])
}

func PROCESS_PARA() {
	if isFirstRecord() {
		WsPrevBranch = currentLedgerRec.BrBranch
		WsPrevAcct = currentLedgerRec.BrAcct
		WsFirstFlag = "N"
	} else {
		if currentLedgerRec.BrBranch != WsPrevBranch {
			ACCT_BREAK_PARA()
			BRANCH_BREAK_PARA()
			WsPrevBranch = currentLedgerRec.BrBranch
			WsPrevAcct = currentLedgerRec.BrAcct
		} else {
			if currentLedgerRec.BrAcct != WsPrevAcct {
				ACCT_BREAK_PARA()
				WsPrevAcct = currentLedgerRec.BrAcct
			}
		}
	}
	POST_PARA()
	READ_PARA()
}

func POST_PARA() {
	WsAmtEd = formatAmtEd(currentLedgerRec.BrAmt)
	switch currentLedgerRec.BrType {
	case "D":
		WsBal = WsBal.Add(currentLedgerRec.BrAmt)
		fmt.Printf("%s D %s\n", currentLedgerRec.BrAcct, WsAmtEd)
	case "C":
		WsBal = WsBal.Sub(currentLedgerRec.BrAmt)
		fmt.Printf("%s C %s\n", currentLedgerRec.BrAcct, WsAmtEd)
	default:
		WsSkipped++
		fmt.Printf("%s ? SKIPPED\n", currentLedgerRec.BrAcct)
	}
