	WsTotEd = formatTotEd(WsGrandTot)
	fmt.Printf("GRAND TOTAL:%s\n", WsTotEd)
	// DISPLAY "SKIPPED: " WS-SKIPPED.  WS-SKIPPED is PIC 99 => zero-padded? But DISPLAY of numeric item with X? In original, WsSkipped is numeric. DISPLAY prints as numeric with leading zeros? Original DISPLAY "SKIPPED: " WS-SKIPPED -> numeric field PIC 99 displays zero-padded to 2 digits per rule. However many COBOLs display without leading zeros? Requirement says unedited numeric prints zero-padded. So format as %02d
	// But need to reproduce exactly. Check: PIC 99 len 2, value 0 => "00". COBOL might display "00". We'll follow spec.
	fmt.Printf("SKIPPED: %02d\n", WsSkipped)
}

